import re, datetime, os

def fmt_to_regex(fmt):
    replacements = {
        '%Y': r'\d{4}',
        '%y': r'\d{2}',
        '%m': r'\d{2}',
        '%d': r'\d{2}',
        '%H': r'\d{2}',
        '%M': r'\d{2}',
        '%S': r'\d{2}',
    }
    group_map = {'%Y': 'Y', '%y': 'y', '%m': 'm', '%d': 'd', '%H': 'H', '%M': 'M', '%S': 'S'}

    result = ''
    i = 0
    used_groups = set()

    while i < len(fmt):
        matched = False
        for code, pat in replacements.items():
            if fmt[i:i+len(code)] == code:
                gname = group_map[code]
                if gname not in used_groups:
                    result += f'(?P<{gname}>{pat})'
                    used_groups.add(gname)
                else:
                    result += pat
                i += len(code)
                matched = True
                break
        if not matched:
            result += re.escape(fmt[i])
            i += 1
    return result

def parse_log_filename(filename, fmt):
    try:
        pattern = '^' + fmt_to_regex(fmt) + '$'
        m = re.match(pattern, filename)
        if not m:
            return None
        groups = m.groupdict()
        year = int(groups.get('Y', 0) or groups.get('y', 0))
        if 'y' in groups and 'Y' not in groups:
            year += 2000 if year < 70 else 1900
        month = int(groups.get('m', 1))
        day = int(groups.get('d', 1))
        return datetime.date(year, month, day)
    except (ValueError, re.error):
        return None

def get_all_log_dates(log_dir, fmt):
    dates = []
    dir_part = os.path.dirname(fmt)

    if dir_part:
        # Has subdirectory structure
        try:
            entries = os.scandir(log_dir)
        except OSError:
            return dates

        for entry in entries:
            if not entry.is_dir() or entry.name.startswith('.'):
                continue
            subdir_path = entry.path
            try:
                for file_entry in os.scandir(subdir_path):
                    if file_entry.name.startswith('.'):
                        continue
                    rel = os.path.join(entry.name, file_entry.name)
                    date = parse_log_filename(rel, fmt)
                    if date:
                        dates.append(date)
            except OSError:
                continue
    else:
        try:
            for entry in os.scandir(log_dir):
                if entry.name.startswith('.') or not entry.is_file():
                    continue
                date = parse_log_filename(entry.name, fmt)
                if date:
                    dates.append(date)
        except OSError:
            pass

    return sorted(dates)

