    """Parse a log filename to get the date. Returns None if doesn't match."""
    try:
        pattern = '^' + fmt_to_regex(fmt) + '$'
        m = re.match(pattern, filename)
        if not m:
            return None

        groups = m.groupdict()
        year = int(groups.get('Y', 0) or groups.get('y', 0) or 0)
        if 'y' in groups and 'Y' not in groups:
            year += 2000 if year < 70 else 1900
        month = int(groups.get('m', 1))
        day = int(groups.get('d', 1))

        return datetime.date(year, month, day)
    except (ValueError, re.error, AttributeError):
        return None


