def draw_hline(win, y, x, width, ch='─'):
    rows, cols = win.getmaxyx()
    if y < 0 or y >= rows:
        return
    available = cols - x
    if available <= 0:
        return
    try:
        win.addstr(y, x, (ch * width)[:available])
    except curses.error:
        pass


def safe_addstr(win, y, x, text, attr=curses.A_NORMAL):
    rows, cols = win.getmaxyx()
    if y < 0 or y >= rows or x < 0 or x >= cols:
        return
    available = cols - x
    if available <= 0:
        return
    try:
        win.addstr(y, x, text[:available], attr)
    except curses.error:
        pass


def draw_box(win, y, x, width, height, title=""):
    """Draw a rounded box"""
    if height < 2 or width < 2:
        return
    rows, cols = win.getmaxyx()

    inner_w = width - 2
    # Top
    top = "╭" + title + "─" * max(0, inner_w - len(title)) + "╮"
    safe_addstr(win, y, x, top[:width])

    # Sides
    for i in range(1, height - 1):
        if y + i < rows:
            safe_addstr(win, y + i, x, "│")
            if x + width - 1 < cols:
                safe_addstr(win, y + i, x + width - 1, "│")

    # Bottom
    bottom = "╰" + "─" * inner_w + "╯"
    safe_addstr(win, y + height - 1, x, bottom[:width])


def draw_month_box(win, y, x, width, height, title, month, year,
                   log_dates_set, cursor_date, focus_calendar,
                   sunday_start, highlighted_dates=None,
                   today=None):
    """Draw a single month calendar box"""
    rows, cols = win.getmaxyx()
    if width < 2 or height < 2:
        return

    inner_w = width - 2  # Should be 21

    # Top border with month name
    safe_addstr(win, y, x, "╭")
    safe_addstr(win, y, x + 1, title)
    safe_addstr(win, y, x + 1 + len(title), "─" * max(0, inner_w - len(title)))
    safe_addstr(win, y, x + width - 1, "╮")

    # Day headers (Mon=first or Sun=first)
    if sunday_start:
        day_header = " S  M  T  W  T  F  S "
    else:
        day_header = " M  T  W  T  F  S  S "
    safe_addstr(win, y + 1, x, "│")
    safe_addstr(win, y + 1, x + 1, day_header[:inner_w], curses.A_UNDERLINE)
    safe_addstr(win, y + 1, x + width - 1, "│")

    # Calendar weeks
    if sunday_start:
        calendar.setfirstweekday(6)  # Sunday
    else:
        calendar.setfirstweekday(0)  # Monday

    weeks = calendar.monthcalendar(year, month)

    for wi, week in enumerate(weeks):
        wy = y + 2 + wi
        if wy >= y + height - 1:
            break

        safe_addstr(win, wy, x, "│")
        safe_addstr(win, wy, x + width - 1, "│")

        for di, day in enumerate(week):
            dx = x + 1 + di * 3
            if day == 0:
                safe_addstr(win, wy, dx, "   ")
            else:
                d = datetime.date(year, month, day)

                # Determine display style
                if today is None:
                    today = datetime.date.today()

                # Weekend check
                if sunday_start:
                    is_weekend = (di == 0 or di == 6)
                else:
                    is_weekend = (di >= 5)

                # Log entry check
                has_log = (d in log_dates_set)
                is_today = (d == today)
                is_cursor = (d == cursor_date)
                is_highlighted = highlighted_dates and (d in highlighted_dates)

                attr = curses.A_NORMAL

                if is_cursor and focus_calendar:
                    attr = curses.A_REVERSE
                elif is_today:
                    attr = curses.color_pair(2) | curses.A_BOLD
                elif is_highlighted:
                    attr = curses.color_pair(3) | curses.A_BOLD
                elif has_log:
                    attr = curses.A_BOLD
                elif is_weekend:
                    attr = curses.color_pair(1)

                safe_addstr(win, wy, dx, f"{day:2d}", attr)
                safe_addstr(win, wy, dx + 2, " ")

    # Empty rows
    for i in range(len(weeks) + 2, height - 1):
        wy = y + i
        if wy < rows and wy < y + height - 1:
            safe_addstr(win, wy, x, "│")
            safe_addstr(win, wy, x + 1, " " * inner_w)
            safe_addstr(win, wy, x + width - 1, "│")

    # Bottom border
    safe_addstr(win, y + height - 1, x, "╰")
    safe_addstr(win, y + height - 1, x + 1, "─" * inner_w)
    safe_addstr(win, y + height - 1, x + width - 1, "╯")


# ─────────────────────────────────────────────
# Main TUI Class
# ─────────────────────────────────────────────

class CapsLogTUI:
    MONTH_W = 23  # 21 inner + 2 borders

    def __init__(self, stdscr, log_dir, log_fmt, sunday_start, first_line_section):
        self.stdscr = stdscr
        self.log_dir = log_dir
        self.log_fmt = log_fmt
        self.sunday_start = sunday_start
        self.first_line_section = first_line_section

        self.today = datetime.date.today()
        self.current_year = self.today.year
        self.cursor_date = self.today

        # Focus: 0=sections, 1=tags, 2=calendar
        self.focus = 0

        # Menu cursor positions
        self.section_cursor = 0  # 0 = <select none>
        self.tag_cursor = 0      # 0 = <select none>

        # Currently selected filter
        self.selected_section = None
        self.selected_tag = None

        # Scratchpad state
        self.scratchpad_mode = False
        self.scratchpad_cursor = 0

        # Initialize colors
        curses.start_color()
        curses.use_default_colors()
        curses.init_pair(1, curses.COLOR_BLUE, -1)   # weekend
        curses.init_pair(2, curses.COLOR_RED, -1)    # today
        curses.init_pair(3, curses.COLOR_YELLOW, -1) # highlighted
        curses.init_pair(4, curses.COLOR_GREEN, -1)  # event

        curses.curs_set(0)

        # Load data
        self.refresh_data()

    def refresh_data(self):
        """Reload all log data"""
        self.all_dates = get_all_log_dates(self.log_dir, self.log_fmt)
        self.all_dates_set = set(self.all_dates)
        self.year_dates = [d for d in self.all_dates if d.year == self.current_year]

        (self.sections_count,
         self.tags_by_section,
         self.root_tags_count,
         self.dates_by_section,
         self.dates_by_tag) = collect_all_data(
            self.log_dir, self.log_fmt, self.current_year,
            self.first_line_section)

        self.sections_list = sorted(self.sections_count.items())

        # Build tags list based on selected section
        self._rebuild_tags_list()

        # Load scratchpads
        scratch_dir = os.path.join(self.log_dir, SCRATCHPAD_DIR)
        try:
            self.scratchpads = sorted([
                f for f in os.listdir(scratch_dir)
                if not f.startswith('.')
            ])
        except OSError:
            self.scratchpads = []

    def _rebuild_tags_list(self):
        """Rebuild the tags list based on current section selection"""
        if self.selected_section is None:
            # Show all tags
            all_tags = {}
            for section_tags in self.tags_by_section.values():
                for tag, count in section_tags.items():
                    all_tags[tag] = all_tags.get(tag, 0) + count
            for tag, count in self.root_tags_count.items():
                all_tags[tag] = all_tags.get(tag, 0) + count
            self.tags_list = sorted(all_tags.items())
        else:
            section_tags = self.tags_by_section.get(self.selected_section, {})
            self.tags_list = sorted(section_tags.items())

    def get_layout(self):
        """Calculate layout sizes for current terminal"""
        rows, cols = self.stdscr.getmaxyx()

        MAX_CONTENT = 144
        content = min(MAX_CONTENT, max(1, cols - 1))

        if content >= MAX_CONTENT:
            left_margin = (cols - 1 - MAX_CONTENT) // 2
        else:
            left_margin = 0

        # Sections and tags each get min(25, ...) width
        # When content >= 100: each panel = 25
        # When content < 100: scale proportionally
        if content >= 100:
            sections_w = 25
            tags_w = 25
        elif content >= 50:
            # Scale panels proportionally, min panel size ~ content/4
            panel_total = content // 2
            panel_total = min(50, panel_total)
            sections_w = (panel_total + 1) // 2
            tags_w = panel_total // 2
        else:
            # Very small: give panels 2/3
            panel_total = (content * 2 + 2) // 3
            sections_w = (panel_total + 1) // 2
            tags_w = panel_total // 2

        calendar_w = content - sections_w - tags_w

        sections_x = left_margin
        tags_x = left_margin + sections_w
        calendar_x = left_margin + sections_w + tags_w

        return {
            'rows': rows, 'cols': cols,
            'content': content, 'left_margin': left_margin,
            'sections_w': sections_w, 'tags_w': tags_w, 'calendar_w': calendar_w,
            'sections_x': sections_x, 'tags_x': tags_x, 'calendar_x': calendar_x,
        }

    def get_highlighted_dates(self):
        """Get dates to highlight based on current selection"""
        if self.selected_tag is not None:
            if self.selected_section is not None:
                key = (self.selected_section, self.selected_tag)
            else:
                # Search across all sections
                dates = set()
                for section in list(self.tags_by_section.keys()) + [None]:
                    key = (section, self.selected_tag)
                    dates.update(self.dates_by_tag.get(key, []))
                return dates
            return set(self.dates_by_tag.get(key, []))
        elif self.selected_section is not None:
            return set(self.dates_by_section.get(self.selected_section, []))
        return None

    def draw(self):
        """Draw the full TUI"""
        if self.scratchpad_mode:
            self.draw_scratchpad()
            return

        self.stdscr.erase()
        layout = self.get_layout()
        rows = layout['rows']
        cols = layout['cols']
        content = layout['content']
        left_margin = layout['left_margin']

        # Header
        year_count = len(self.year_dates)
        header = (f"Today is: {self.today.day:02d}. {self.today.month:02d}. "
                  f"{self.today.year}.  | There are {year_count} log entries "
                  f"for year {self.current_year}.")
        hx = left_margin + max(0, (content - len(header) + 1) // 2)
        safe_addstr(self.stdscr, 0, hx, header, curses.A_BOLD | curses.A_UNDERLINE)

        # Calculate heights
        # The calendar and side panels take up to rows-4 height
        # Preview box takes remaining
        # Events box: 2 rows (title+bottom) below side panels

        # Sections/Tags height: calculated from number of items
        max_section_items = len(self.sections_list) + 1  # +1 for <select none>
        max_tag_items = len(self.tags_list) + 1

        # Calendar height based on terminal height
        available_rows = rows - 1  # leave 1 for header

        # Calculate calendar rows needed for 12 months
        months_per_row = max(1, layout['calendar_w'] // self.MONTH_W)
        month_rows = 0
        for row in range(0, 12, months_per_row):
            group_end = min(row + months_per_row, 12)
            max_weeks = max(len(calendar.monthcalendar(self.current_year, m + 1))
                          for m in range(row, group_end))
            month_rows += max_weeks + 3  # header + day names + weeks + empty
        month_rows += 2  # outer box top/bottom

        # Side panel height = min(month_rows, # items)
        panel_height = min(month_rows, max(3, max(max_section_items, max_tag_items) + 2))

        # Events box (below panels)
        events_y = 1 + panel_height

        # Preview box (below everything)
        status_bar_height = 1
        preview_start = max(events_y + 2, 1 + month_rows + 2)
        preview_height = rows - preview_start - status_bar_height
        if preview_height < 3:
            preview_height = 3
            preview_start = rows - preview_height - status_bar_height

        # Draw sections panel
        self.draw_sections(1, layout['sections_x'], layout['sections_w'], panel_height)

        # Draw tags panel
        self.draw_tags(1, layout['tags_x'], layout['tags_w'], panel_height)

        # Draw calendar
        self.draw_calendar(1, layout['calendar_x'], layout['calendar_w'],
                          rows - preview_height - 2)

        # Draw events box
        events_w = layout['sections_w'] + layout['tags_w']
        self.draw_events(events_y, layout['sections_x'], events_w)

        # Draw preview
        if preview_start < rows - 3:
            preview_w = content
            self.draw_preview(preview_start, left_margin, preview_w, preview_height)

        # Status bar
        status = ("hjkl/arrow keys - navigation | d - delete log | "
                  "s - see scratchpads | tab - move focus between menus and calendar")
        status_y = rows - 1
        sx = left_margin + max(0, (content - len(status) + 1) // 2)
        safe_addstr(self.stdscr, status_y, sx, status)

        self.stdscr.refresh()

    def draw_sections(self, y, x, width, height):
        """Draw sections menu"""
        if width < 3 or height < 3:
            return

        inner_w = width - 2
        title = "Sections"
        draw_box(self.stdscr, y, x, width, height, title)

        items = [None] + [s[0] for s in self.sections_list]
        focused = (self.focus == 0)

        for i, item in enumerate(items):
            if i >= height - 2:
                break

            item_y = y + 1 + i
            item_x = x + 1

            if item is None:
                name = "<select none>"
                count_str = ""
                display = f"  {name}"
            else:
                count = self.sections_count.get(item, 0)
                count_str = f"{count:4d} \u2502 "
                available_name = inner_w - len(count_str) - 2
                name = item[:available_name]
                display = f"  {count_str}{name}"

            is_cursor = (i == self.section_cursor)
            if is_cursor:
                display = ">" + display[1:]

            display = display[:inner_w].ljust(inner_w)[:inner_w]

            attr = curses.A_NORMAL
            if is_cursor and focused:
                attr = curses.A_REVERSE
            elif is_cursor:
                attr = curses.A_BOLD

            safe_addstr(self.stdscr, item_y, item_x, display, attr)

    def draw_tags(self, y, x, width, height):
        """Draw tags menu"""
        if width < 3 or height < 3:
            return

        inner_w = width - 2
        title = "Tags"
        draw_box(self.stdscr, y, x, width, height, title)

        items = [None] + [t[0] for t in self.tags_list]
        focused = (self.focus == 1)

        for i, item in enumerate(items):
            if i >= height - 2:
                break

            item_y = y + 1 + i
            item_x = x + 1

            if item is None:
                name = "<select none>"
                display = f"  {name}"
            else:
                # Calculate count for this tag
                if self.selected_section is None:
                    count = sum(
                        sec_tags.get(item, 0)
                        for sec_tags in self.tags_by_section.values()
                    ) + self.root_tags_count.get(item, 0)
                else:
                    count = self.tags_by_section.get(
                        self.selected_section, {}).get(item, 0)

                count_str = f"{count:4d} \u2502 "
                available_name = inner_w - len(count_str) - 2
                name = item[:available_name]
                display = f"  {count_str}{name}"

            is_cursor = (i == self.tag_cursor)
            if is_cursor:
                display = ">" + display[1:]

            display = display[:inner_w].ljust(inner_w)[:inner_w]

            attr = curses.A_NORMAL
            if is_cursor and focused:
                attr = curses.A_REVERSE
            elif is_cursor:
                attr = curses.A_BOLD

            safe_addstr(self.stdscr, item_y, item_x, display, attr)

    def draw_calendar(self, y, x, width, height):
        """Draw annual calendar with all 12 months"""
        if width < 3 or height < 3:
            return

        inner_w = width - 2
        title = str(self.current_year)
        draw_box(self.stdscr, y, x, width, height, title)

        months_per_row = max(1, inner_w // self.MONTH_W)
        highlighted = self.get_highlighted_dates()

        month_y = y + 1
        for row_start in range(0, 12, months_per_row):
            row_end = min(row_start + months_per_row, 12)

            # Calculate max weeks for this row of months
            max_weeks = max(
                len(calendar.monthcalendar(self.current_year, m + 1))
                for m in range(row_start, row_end)
            )
            row_height = max_weeks + 3  # title + day_header + weeks

            if month_y + row_height > y + height - 1:
                break

            for mi, m in enumerate(range(row_start, row_end)):
                month_num = m + 1
                mx = x + 1 + mi * self.MONTH_W
                if mx + self.MONTH_W > x + width:
                    break
                month_name = datetime.date(self.current_year, month_num, 1).strftime("%B")
                draw_month_box(
                    self.stdscr, month_y, mx, self.MONTH_W, row_height,
                    month_name, month_num, self.current_year,
                    self.all_dates_set, self.cursor_date,
                    self.focus == 2, self.sunday_start,
                    highlighted, self.today
                )

            month_y += row_height
            if month_y < y + height - 1:
                # Separator line between rows is just the bottom of month boxes
                pass

        # Right border
        for i in range(1, height - 1):
            safe_addstr(self.stdscr, y + i, x + width - 1, "│")

    def draw_events(self, y, x, width):
        """Draw recent & upcoming events box"""
        rows, cols = self.stdscr.getmaxyx()
        if y >= rows - 1:
            return
        events_count = 0  # TODO: implement actual events
        title = f"Recent & upcoming events ({events_count})"
        inner_w = width - 2
        top = "╭" + title + "─" * max(0, inner_w - len(title)) + "╮"
        bottom = "╰" + "─" * inner_w + "╯"
        safe_addstr(self.stdscr, y, x, top[:width])
        safe_addstr(self.stdscr, y + 1, x, bottom[:width])

    def draw_preview(self, y, x, width, height):
        """Draw log entry preview"""
        rows, cols = self.stdscr.getmaxyx()
        if y >= rows or height < 3:
            return

        inner_w = width - 2
        draw_box(self.stdscr, y, x, width, height)

        # Title
        date_str = (f"{self.cursor_date.day:02d}. {self.cursor_date.month:02d}. "
                    f"{str(self.cursor_date.year)[2:]}.")
        title = f"log preview for {date_str}"
        tx = x + 1 + max(0, (inner_w - len(title) + 1) // 2)
        safe_addstr(self.stdscr, y + 1, tx, title,
                   curses.A_UNDERLINE | curses.A_BOLD)

        # Content
        log_path = get_log_filename(self.log_dir, self.cursor_date, self.log_fmt)
        if os.path.exists(log_path):
            try:
                with open(log_path, 'r', encoding='utf-8', errors='replace') as f:
                    lines = f.readlines()
                for i, line in enumerate(lines):
                    if i >= height - 3:
                        break
                    line = line.rstrip('\n').rstrip('\r')[:inner_w]
                    # Simple markdown rendering
                    attr = curses.A_NORMAL
                    if line.startswith('# '):
                        attr = curses.A_BOLD
                    elif line.startswith('## '):
                        attr = curses.A_BOLD
                    elif line.startswith('* '):
                        attr = curses.color_pair(1)
                    safe_addstr(self.stdscr, y + 2 + i, x + 1, line, attr)
            except OSError:
                pass

    def draw_scratchpad(self):
        """Draw scratchpad manager"""
        self.stdscr.erase()
        rows, cols = self.stdscr.getmaxyx()

        # Title bar
        title = "Scratchpad Manager"
        tx = max(0, (cols - len(title) + 1) // 2)
        safe_addstr(self.stdscr, 0, tx, title, curses.A_BOLD)
        safe_addstr(self.stdscr, 1, 0, "─" * cols)

