            self.stdscr.addstr(dlg_y + 4, btn_x, "┌" + "─" * (len(btn) + 2) + "┐")
            self.stdscr.addstr(dlg_y + 5, dlg_x, "│" + " " * inner_w + "│")
            self.stdscr.addstr(dlg_y + 5, btn_x, "│ " + btn + " │")
            self.stdscr.addstr(dlg_y + 6, dlg_x, "│" + " " * inner_w + "│")
            self.stdscr.addstr(dlg_y + 6, btn_x, "└" + "─" * (len(btn) + 2) + "┘")
            self.stdscr.addstr(dlg_y + 7, dlg_x, "╰" + "─" * inner_w + "╯")
        except curses.error:
            pass

        # Input field
        input_y = dlg_y + 3
        input_x = dlg_x + 2
        input_w = inner_w - 2

        curses.curs_set(1)
        self.stdscr.move(input_y, input_x)
        self.stdscr.refresh()

        chars = []
        while True:
            try:
                key = self.stdscr.get_wch()
            except curses.error:
                break

            if isinstance(key, str):
                code = ord(key)
            else:
                code = key

            if code in (10, 13):  # Enter
                break
            elif code in (curses.KEY_BACKSPACE, 127, 8):
                if chars:
                    chars.pop()
                    try:
                        self.stdscr.addstr(input_y, input_x, " " * input_w)
                        self.stdscr.addstr(input_y, input_x, "*" * len(chars))
                        self.stdscr.move(input_y, input_x + len(chars))
                        self.stdscr.refresh()
                    except curses.error:
                        pass
            elif 32 <= code < 256 and len(chars) < input_w:
                chars.append(chr(code))
                try:
                    self.stdscr.addstr(input_y, input_x + len(chars) - 1, "*")
                    self.stdscr.refresh()
                except curses.error:
                    pass

        curses.curs_set(0)
        self.stdscr.bkgd(' ', curses.A_NORMAL)
        return "".join(chars)

    def run(self):
        """Main event loop"""
        self.stdscr.nodelay(False)
        while True:
            self.draw()
            try:
                key = self.stdscr.get_wch()
                if isinstance(key, str):
                    key = ord(key)
            except KeyboardInterrupt:
                break
            except curses.error:
                continue
            if not self.handle_key(key):
                break


