def fmt_to_regex(fmt: str) -> str:
    """Convert strftime format to regex pattern, handling duplicate codes"""
    replacements = {
        '%Y': r'\d{4}',
        '%y': r'\d{2}',
        '%m': r'\d{2}',
        '%d': r'\d{2}',
        '%H': r'\d{2}',
        '%M': r'\d{2}',
        '%S': r'\d{2}',
    }
    group_map = {
        '%Y': 'Y', '%y': 'y', '%m': 'm', '%d': 'd',
        '%H': 'H', '%M': 'M', '%S': 'S'
    }

    result = ''
    i = 0
    used_groups = set()

    while i < len(fmt):
        matched = False
        for code, pat in replacements.items():
            if fmt[i:i+len(code)] == code:
                gname = group_map[code]
                if gname not in used_groups:
                    result += f'(?P<{gname}>{pat})'
                    used_groups.add(gname)
                else:
                    result += pat
                i += len(code)
                matched = True
                break
        if not matched:
            result += re.escape(fmt[i])
            i += 1
    return result


def parse_log_filename(filename: str, fmt: str):
    """Parse a log filename to get the date. Returns None if doesn't match."""
    try:
        pattern = '^' + fmt_to_regex(fmt) + '$'
        m = re.match(pattern, filename)
        if not m:
            return None

        groups = m.groupdict()
        year = int(groups.get('Y', 0) or groups.get('y', 0) or 0)
        if 'y' in groups and 'Y' not in groups:
            year += 2000 if year < 70 else 1900
        month = int(groups.get('m', 1))
        day = int(groups.get('d', 1))

        return datetime.date(year, month, day)
    except (ValueError, re.error, AttributeError):
        return None


def get_log_filename(log_dir: str, date: datetime.date, fmt: str) -> str:
    """Get the full path for a log file given a date and format"""
    rel_path = date.strftime(fmt)
    return os.path.join(log_dir, rel_path)


def get_all_log_dates(log_dir: str, fmt: str) -> list:
    """Get all log dates from the log directory"""
    dates = []
    dir_part = os.path.dirname(fmt)

    if dir_part:
        # Has subdirectory structure
        try:
            entries = list(os.scandir(log_dir))
        except OSError:
            return dates

        for entry in entries:
            if not entry.is_dir() or entry.name.startswith('.'):
                continue
            try:
                for file_entry in os.scandir(entry.path):
                    if file_entry.name.startswith('.'):
                        continue
                    rel = os.path.join(entry.name, file_entry.name).replace('\\', '/')
                    date = parse_log_filename(rel, fmt)
                    if date:
                        dates.append(date)
            except OSError:
                continue
    else:
        try:
            for entry in os.scandir(log_dir):
                if entry.name.startswith('.') or not entry.is_file():
                    continue
                date = parse_log_filename(entry.name, fmt)
                if date:
                    dates.append(date)
        except OSError:
            pass

    return sorted(set(dates))


def parse_log_file(filepath: str, first_line_section: bool = False) -> dict:
    """
    Parse a log file and extract sections and tags.
    Returns dict with 'sections': {section_name: [tags]}, 'root_tags': [tags]
    """
    try:
        with open(filepath, 'r', encoding='utf-8', errors='replace') as f:
            lines = f.readlines()
    except OSError:
        return {'sections': {}, 'root_tags': []}

    sections = {}
    root_tags = []
    current_section = None

    for i, line in enumerate(lines):
        line = line.rstrip('\n').rstrip('\r')

        # Skip first line if not first_line_section
        if i == 0 and not first_line_section:
            continue

        # Check for section header (level 1: single # but not ##)
        if re.match(r'^# [^#]', line):
            section_name = line[2:].strip().lower()
            if section_name:
                current_section = section_name
                if current_section not in sections:
                    sections[current_section] = []
        elif line.startswith('* '):
            # Tag line
            tag_text = line[2:].strip()
            # Parse tag name (before ' (', ':', or whitespace)
            m = re.match(r'^([^\s(:]+)', tag_text)
            if not m:
                continue
            tag_name = m.group(1).lower()
            if not tag_name:
                continue

            if current_section is not None:
                sections[current_section].append(tag_name)
            else:
                root_tags.append(tag_name)

    return {'sections': sections, 'root_tags': root_tags}


def collect_all_data(log_dir: str, fmt: str, year: int,
                     first_line_section: bool = False) -> tuple:
    """
    Collect all sections and tags from log files for a given year.
    Returns (sections_count, tags_by_section, root_tags_count, dates_by_section, dates_by_tag)
    """
    dates = get_all_log_dates(log_dir, fmt)
    year_dates = [d for d in dates if d.year == year]

    sections_count = {}
    tags_by_section = {}
    root_tags_count = {}
    dates_by_section = {}   # section -> list of dates
    dates_by_tag = {}       # (section or None, tag) -> list of dates

    for date in year_dates:
        filepath = get_log_filename(log_dir, date, fmt)
        if not os.path.exists(filepath):
            continue

        parsed = parse_log_file(filepath, first_line_section)

        # Process sections
        for section_name, tags in parsed['sections'].items():
            sections_count[section_name] = sections_count.get(section_name, 0) + 1
            if section_name not in tags_by_section:
                tags_by_section[section_name] = {}
            if section_name not in dates_by_section:
                dates_by_section[section_name] = []
            dates_by_section[section_name].append(date)

            for tag in tags:
                tags_by_section[section_name][tag] = \
                    tags_by_section[section_name].get(tag, 0) + 1
                key = (section_name, tag)
                if key not in dates_by_tag:
                    dates_by_tag[key] = []
                dates_by_tag[key].append(date)

        # Process root tags
        for tag in parsed['root_tags']:
            root_tags_count[tag] = root_tags_count.get(tag, 0) + 1
            key = (None, tag)
            if key not in dates_by_tag:
                dates_by_tag[key] = []
            dates_by_tag[key].append(date)

    return (sections_count, tags_by_section, root_tags_count,
            dates_by_section, dates_by_tag)


def do_encrypt(log_dir: str, password: str):
    """Apply encryption (create .cle file)"""
    print("Applying crypto...")

    if has_cle(log_dir):
        error_exit("Already applied")

    try:
        write_cle(log_dir, password)
    except OSError as e:
        error_exit(str(e))


def do_decrypt(log_dir: str, password: str):
    """Remove encryption (remove .cle file)"""
    print("Applying crypto...")

    if not has_cle(log_dir):
        error_exit("Already applied")

    cle_path = os.path.join(log_dir, CLE_FILENAME)
    try:
        os.remove(cle_path)
    except OSError as e:
        error_exit(str(e))


def parse_config(config_path: str) -> dict:
    """Parse INI config file"""
    config = {}

    try:
        with open(config_path, 'r') as f:
            content = f.read()
    except FileNotFoundError:
        raise FileNotFoundError(f"Failed to open file: {config_path}")
    except IOError:
        raise FileNotFoundError(f"Failed to open file: {config_path}")

    parser = configparser.RawConfigParser()
    try:
        parser.read_string(content)
    except Exception:
        pass

    # Read top-level options (defaults)
    if parser.defaults():
        for key, value in parser.defaults().items():
            config[key] = value

    for section in parser.sections():
        for key, value in parser.items(section):
            config[f"{section}.{key}"] = value

    # Parse boolean fields
    for key in ['sunday-start', 'first-line-section']:
        if key in config:
            config[key] = config[key].lower() in ('true', '1', 'yes')

    return config


