def draw_hline(win, y, x, width, ch='─'):
    rows, cols = win.getmaxyx()
    if y < 0 or y >= rows:
        return
    available = cols - x
    if available <= 0:
        return
    try:
        win.addstr(y, x, (ch * width)[:available])
    except curses.error:
        pass


def safe_addstr(win, y, x, text, attr=curses.A_NORMAL):
    rows, cols = win.getmaxyx()
    if y < 0 or y >= rows or x < 0 or x >= cols:
        return
    available = cols - x
    if available <= 0:
        return
    try:
        win.addstr(y, x, text[:available], attr)
    except curses.error:
        pass


def draw_box(win, y, x, width, height, title=""):
    """Draw a rounded box"""
    if height < 2 or width < 2:
        return
    rows, cols = win.getmaxyx()

    inner_w = width - 2
    # Top
    top = "╭" + title + "─" * max(0, inner_w - len(title)) + "╮"
    safe_addstr(win, y, x, top[:width])

    # Sides
    for i in range(1, height - 1):
        if y + i < rows:
            safe_addstr(win, y + i, x, "│")
            if x + width - 1 < cols:
                safe_addstr(win, y + i, x + width - 1, "│")

    # Bottom
    bottom = "╰" + "─" * inner_w + "╯"
    safe_addstr(win, y + height - 1, x, bottom[:width])


def draw_month_box(win, y, x, width, height, title, month, year,
                   log_dates_set, cursor_date, focus_calendar,
                   sunday_start, highlighted_dates=None,
                   today=None):
    """Draw a single month calendar box"""
    rows, cols = win.getmaxyx()
    if width < 2 or height < 2:
        return

    inner_w = width - 2  # Should be 21

    # Top border with month name
    safe_addstr(win, y, x, "╭")
    safe_addstr(win, y, x + 1, title)
    safe_addstr(win, y, x + 1 + len(title), "─" * max(0, inner_w - len(title)))
    safe_addstr(win, y, x + width - 1, "╮")

    # Day headers (Mon=first or Sun=first)
    if sunday_start:
        day_header = " S  M  T  W  T  F  S "
    else:
        day_header = " M  T  W  T  F  S  S "
    safe_addstr(win, y + 1, x, "│")
    safe_addstr(win, y + 1, x + 1, day_header[:inner_w], curses.A_UNDERLINE)
    safe_addstr(win, y + 1, x + width - 1, "│")

    # Calendar weeks
    if sunday_start:
        calendar.setfirstweekday(6)  # Sunday
    else:
        calendar.setfirstweekday(0)  # Monday

    weeks = calendar.monthcalendar(year, month)

    for wi, week in enumerate(weeks):
        wy = y + 2 + wi
        if wy >= y + height - 1:
            break

        safe_addstr(win, wy, x, "│")
        safe_addstr(win, wy, x + width - 1, "│")

        for di, day in enumerate(week):
            dx = x + 1 + di * 3
            if day == 0:
                safe_addstr(win, wy, dx, "   ")
            else:
                d = datetime.date(year, month, day)

                # Determine display style
                if today is None:
                    today = datetime.date.today()

                # Weekend check
                if sunday_start:
                    is_weekend = (di == 0 or di == 6)
                else:
                    is_weekend = (di >= 5)

                # Log entry check
                has_log = (d in log_dates_set)
                is_today = (d == today)
                is_cursor = (d == cursor_date)
                is_highlighted = highlighted_dates and (d in highlighted_dates)

                attr = curses.A_NORMAL

                if is_cursor and focus_calendar:
                    attr = curses.A_REVERSE
                elif is_today:
                    attr = curses.color_pair(2) | curses.A_BOLD
                elif is_highlighted:
                    attr = curses.color_pair(3) | curses.A_BOLD
                elif has_log:
                    attr = curses.A_BOLD
                elif is_weekend:
                    attr = curses.color_pair(1)

                safe_addstr(win, wy, dx, f"{day:2d}", attr)
                safe_addstr(win, wy, dx + 2, " ")

    # Empty rows
    for i in range(len(weeks) + 2, height - 1):
        wy = y + i
        if wy < rows and wy < y + height - 1:
            safe_addstr(win, wy, x, "│")
            safe_addstr(win, wy, x + 1, " " * inner_w)
            safe_addstr(win, wy, x + width - 1, "│")

    # Bottom border
    safe_addstr(win, y + height - 1, x, "╰")
    safe_addstr(win, y + height - 1, x + 1, "─" * inner_w)
    safe_addstr(win, y + height - 1, x + width - 1, "╯")


# ─────────────────────────────────────────────
# Main TUI Class
# ─────────────────────────────────────────────

class CapsLogTUI:
    MONTH_W = 23  # 21 inner + 2 borders

    def __init__(self, stdscr, log_dir, log_fmt, sunday_start, first_line_section):
        self.stdscr = stdscr
        self.log_dir = log_dir
        self.log_fmt = log_fmt
        self.sunday_start = sunday_start
        self.first_line_section = first_line_section

        self.today = datetime.date.today()
        self.current_year = self.today.year
        self.cursor_date = self.today

        # Focus: 0=sections, 1=tags, 2=calendar
        self.focus = 0

        # Menu cursor positions
        self.section_cursor = 0  # 0 = <select none>
        self.tag_cursor = 0      # 0 = <select none>

        # Currently selected filter
        self.selected_section = None
        self.selected_tag = None

        # Scratchpad state
        self.scratchpad_mode = False
        self.scratchpad_cursor = 0

        # Initialize colors
        curses.start_color()
        curses.use_default_colors()
        curses.init_pair(1, curses.COLOR_BLUE, -1)   # weekend
        curses.init_pair(2, curses.COLOR_RED, -1)    # today
        curses.init_pair(3, curses.COLOR_YELLOW, -1) # highlighted
        curses.init_pair(4, curses.COLOR_GREEN, -1)  # event

        curses.curs_set(0)

        # Load data
        self.refresh_data()

    def refresh_data(self):
        """Reload all log data"""
        self.all_dates = get_all_log_dates(self.log_dir, self.log_fmt)
        self.all_dates_set = set(self.all_dates)
        self.year_dates = [d for d in self.all_dates if d.year == self.current_year]

        (self.sections_count,
         self.tags_by_section,
         self.root_tags_count,
         self.dates_by_section,
         self.dates_by_tag) = collect_all_data(
            self.log_dir, self.log_fmt, self.current_year,
            self.first_line_section)

        self.sections_list = sorted(self.sections_count.items())

        # Build tags list based on selected section
        self._rebuild_tags_list()

        # Load scratchpads
        scratch_dir = os.path.join(self.log_dir, SCRATCHPAD_DIR)
        try:
            self.scratchpads = sorted([
                f for f in os.listdir(scratch_dir)
                if not f.startswith('.')
            ])
        except OSError:
            self.scratchpads = []

    def _rebuild_tags_list(self):
        """Rebuild the tags list based on current section selection"""
        if self.selected_section is None:
            # Show all tags
            all_tags = {}
            for section_tags in self.tags_by_section.values():
                for tag, count in section_tags.items():
                    all_tags[tag] = all_tags.get(tag, 0) + count
            for tag, count in self.root_tags_count.items():
                all_tags[tag] = all_tags.get(tag, 0) + count
            self.tags_list = sorted(all_tags.items())
        else:
            section_tags = self.tags_by_section.get(self.selected_section, {})
            self.tags_list = sorted(section_tags.items())

    def get_layout(self):
        """Calculate layout sizes for current terminal"""
        rows, cols = self.stdscr.getmaxyx()

        MAX_CONTENT = 144
        content = min(MAX_CONTENT, max(1, cols - 1))

        if content >= MAX_CONTENT:
            left_margin = (cols - 1 - MAX_CONTENT) // 2
        else:
            left_margin = 0

        # Sections and tags each get min(25, ...) width
        # When content >= 100: each panel = 25
        # When content < 100: scale proportionally
        if content >= 100:
            sections_w = 25
            tags_w = 25
        elif content >= 50:
            # Scale panels proportionally, min panel size ~ content/4
            panel_total = content // 2
            panel_total = min(50, panel_total)
            sections_w = (panel_total + 1) // 2
            tags_w = panel_total // 2
        else:
            # Very small: give panels 2/3
            panel_total = (content * 2 + 2) // 3
            sections_w = (panel_total + 1) // 2
            tags_w = panel_total // 2

        calendar_w = content - sections_w - tags_w

        sections_x = left_margin
        tags_x = left_margin + sections_w
        calendar_x = left_margin + sections_w + tags_w

        return {
            'rows': rows, 'cols': cols,
            'content': content, 'left_margin': left_margin,
            'sections_w': sections_w, 'tags_w': tags_w, 'calendar_w': calendar_w,
            'sections_x': sections_x, 'tags_x': tags_x, 'calendar_x': calendar_x,
        }

    def get_highlighted_dates(self):
        """Get dates to highlight based on current selection"""
        if self.selected_tag is not None:
            if self.selected_section is not None:
                key = (self.selected_section, self.selected_tag)
            else:
                # Search across all sections
                dates = set()
                for section in list(self.tags_by_section.keys()) + [None]:
                    key = (section, self.selected_tag)
                    dates.update(self.dates_by_tag.get(key, []))
                return dates
            return set(self.dates_by_tag.get(key, []))
        elif self.selected_section is not None:
            return set(self.dates_by_section.get(self.selected_section, []))
        return None

    def draw(self):
        """Draw the full TUI"""
        if self.scratchpad_mode:
            self.draw_scratchpad()
            return

        self.stdscr.erase()
        layout = self.get_layout()
        rows = layout['rows']
        cols = layout['cols']
        content = layout['content']
        left_margin = layout['left_margin']

        # Header
        year_count = len(self.year_dates)
        header = (f"Today is: {self.today.day:02d}. {self.today.month:02d}. "
                  f"{self.today.year}.  | There are {year_count} log entries "
                  f"for year {self.current_year}.")
        hx = left_margin + max(0, (content - len(header) + 1) // 2)
        safe_addstr(self.stdscr, 0, hx, header, curses.A_BOLD | curses.A_UNDERLINE)

        # Calculate heights
        # The calendar and side panels take up to rows-4 height
        # Preview box takes remaining
        # Events box: 2 rows (title+bottom) below side panels

        # Sections/Tags height: calculated from number of items
        max_section_items = len(self.sections_list) + 1  # +1 for <select none>
        max_tag_items = len(self.tags_list) + 1

        # Calendar height based on terminal height
        available_rows = rows - 1  # leave 1 for header

        # Calculate calendar rows needed for 12 months
        months_per_row = max(1, layout['calendar_w'] // self.MONTH_W)
        month_rows = 0
        for row in range(0, 12, months_per_row):
            group_end = min(row + months_per_row, 12)
            max_weeks = max(len(calendar.monthcalendar(self.current_year, m + 1))
                          for m in range(row, group_end))
            month_rows += max_weeks + 3  # header + day names + weeks + empty
        month_rows += 2  # outer box top/bottom

        # Side panel height = min(month_rows, # items)
        panel_height = min(month_rows, max(3, max(max_section_items, max_tag_items) + 2))

        # Events box (below panels)
        events_y = 1 + panel_height

        # Preview box (below everything)
        status_bar_height = 1
        preview_start = max(events_y + 2, 1 + month_rows + 2)
        preview_height = rows - preview_start - status_bar_height
        if preview_height < 3:
            preview_height = 3
            preview_start = rows - preview_height - status_bar_height

        # Draw sections panel
        self.draw_sections(1, layout['sections_x'], layout['sections_w'], panel_height)

        # Draw tags panel
        self.draw_tags(1, layout['tags_x'], layout['tags_w'], panel_height)

        # Draw calendar
        self.draw_calendar(1, layout['calendar_x'], layout['calendar_w'],
                          rows - preview_height - 2)

        # Draw events box
        events_w = layout['sections_w'] + layout['tags_w']
        self.draw_events(events_y, layout['sections_x'], events_w)

        # Draw preview
        if preview_start < rows - 3:
            preview_w = content
            self.draw_preview(preview_start, left_margin, preview_w, preview_height)

        # Status bar
        status = ("hjkl/arrow keys - navigation | d - delete log | "
                  "s - see scratchpads | tab - move focus between menus and calendar")
        status_y = rows - 1
        sx = left_margin + max(0, (content - len(status) + 1) // 2)
        safe_addstr(self.stdscr, status_y, sx, status)

        self.stdscr.refresh()

    def draw_sections(self, y, x, width, height):
        """Draw sections menu"""
        if width < 3 or height < 3:
            return

        inner_w = width - 2
        title = "Sections"
        draw_box(self.stdscr, y, x, width, height, title)

        items = [None] + [s[0] for s in self.sections_list]
        focused = (self.focus == 0)

        for i, item in enumerate(items):
            if i >= height - 2:
                break

            item_y = y + 1 + i
            item_x = x + 1

            if item is None:
                name = "<select none>"
                count_str = ""
                display = f"  {name}"
            else:
                count = self.sections_count.get(item, 0)
                count_str = f"{count:4d} \u2502 "
                available_name = inner_w - len(count_str) - 2
                name = item[:available_name]
                display = f"  {count_str}{name}"

            is_cursor = (i == self.section_cursor)
            if is_cursor:
                display = ">" + display[1:]

            display = display[:inner_w].ljust(inner_w)[:inner_w]

            attr = curses.A_NORMAL
            if is_cursor and focused:
                attr = curses.A_REVERSE
            elif is_cursor:
                attr = curses.A_BOLD

            safe_addstr(self.stdscr, item_y, item_x, display, attr)

    def draw_tags(self, y, x, width, height):
        """Draw tags menu"""
        if width < 3 or height < 3:
            return

        inner_w = width - 2
        title = "Tags"
        draw_box(self.stdscr, y, x, width, height, title)

        items = [None] + [t[0] for t in self.tags_list]
        focused = (self.focus == 1)

        for i, item in enumerate(items):
            if i >= height - 2:
                break

            item_y = y + 1 + i
            item_x = x + 1

            if item is None:
                name = "<select none>"
                display = f"  {name}"
            else:
                # Calculate count for this tag
                if self.selected_section is None:
                    count = sum(
                        sec_tags.get(item, 0)
                        for sec_tags in self.tags_by_section.values()
                    ) + self.root_tags_count.get(item, 0)
                else:
                    count = self.tags_by_section.get(
                        self.selected_section, {}).get(item, 0)

                count_str = f"{count:4d} \u2502 "
                available_name = inner_w - len(count_str) - 2
                name = item[:available_name]
                display = f"  {count_str}{name}"

            is_cursor = (i == self.tag_cursor)
            if is_cursor:
                display = ">" + display[1:]

            display = display[:inner_w].ljust(inner_w)[:inner_w]

            attr = curses.A_NORMAL
            if is_cursor and focused:
                attr = curses.A_REVERSE
            elif is_cursor:
                attr = curses.A_BOLD

            safe_addstr(self.stdscr, item_y, item_x, display, attr)

    def draw_calendar(self, y, x, width, height):
        """Draw annual calendar with all 12 months"""
        if width < 3 or height < 3:
            return

        inner_w = width - 2
        title = str(self.current_year)
        draw_box(self.stdscr, y, x, width, height, title)

        months_per_row = max(1, inner_w // self.MONTH_W)
        highlighted = self.get_highlighted_dates()

        month_y = y + 1
        for row_start in range(0, 12, months_per_row):
            row_end = min(row_start + months_per_row, 12)

            # Calculate max weeks for this row of months
            max_weeks = max(
                len(calendar.monthcalendar(self.current_year, m + 1))
                for m in range(row_start, row_end)
            )
            row_height = max_weeks + 3  # title + day_header + weeks

            if month_y + row_height > y + height - 1:
                break

            for mi, m in enumerate(range(row_start, row_end)):
                month_num = m + 1
                mx = x + 1 + mi * self.MONTH_W
                if mx + self.MONTH_W > x + width:
                    break
                month_name = datetime.date(self.current_year, month_num, 1).strftime("%B")
                draw_month_box(
                    self.stdscr, month_y, mx, self.MONTH_W, row_height,
                    month_name, month_num, self.current_year,
                    self.all_dates_set, self.cursor_date,
                    self.focus == 2, self.sunday_start,
                    highlighted, self.today
                )

            month_y += row_height
            if month_y < y + height - 1:
                # Separator line between rows is just the bottom of month boxes
                pass

        # Right border
        for i in range(1, height - 1):
            safe_addstr(self.stdscr, y + i, x + width - 1, "│")

    def draw_events(self, y, x, width):
        """Draw recent & upcoming events box"""
        rows, cols = self.stdscr.getmaxyx()
        if y >= rows - 1:
            return
        events_count = 0  # TODO: implement actual events
        title = f"Recent & upcoming events ({events_count})"
        inner_w = width - 2
        top = "╭" + title + "─" * max(0, inner_w - len(title)) + "╮"
        bottom = "╰" + "─" * inner_w + "╯"
        safe_addstr(self.stdscr, y, x, top[:width])
        safe_addstr(self.stdscr, y + 1, x, bottom[:width])

    def draw_preview(self, y, x, width, height):
        """Draw log entry preview"""
        rows, cols = self.stdscr.getmaxyx()
        if y >= rows or height < 3:
            return

        inner_w = width - 2
        draw_box(self.stdscr, y, x, width, height)

        # Title
        date_str = (f"{self.cursor_date.day:02d}. {self.cursor_date.month:02d}. "
                    f"{str(self.cursor_date.year)[2:]}.")
        title = f"log preview for {date_str}"
        tx = x + 1 + max(0, (inner_w - len(title) + 1) // 2)
        safe_addstr(self.stdscr, y + 1, tx, title,
                   curses.A_UNDERLINE | curses.A_BOLD)

        # Content
        log_path = get_log_filename(self.log_dir, self.cursor_date, self.log_fmt)
        if os.path.exists(log_path):
            try:
                with open(log_path, 'r', encoding='utf-8', errors='replace') as f:
                    lines = f.readlines()
                for i, line in enumerate(lines):
                    if i >= height - 3:
                        break
                    line = line.rstrip('\n').rstrip('\r')[:inner_w]
                    # Simple markdown rendering
                    attr = curses.A_NORMAL
                    if line.startswith('# '):
                        attr = curses.A_BOLD
                    elif line.startswith('## '):
                        attr = curses.A_BOLD
                    elif line.startswith('* '):
                        attr = curses.color_pair(1)
                    safe_addstr(self.stdscr, y + 2 + i, x + 1, line, attr)
            except OSError:
                pass

    def draw_scratchpad(self):
        """Draw scratchpad manager"""
        self.stdscr.erase()
        rows, cols = self.stdscr.getmaxyx()

        # Title bar
        title = "Scratchpad Manager"
        tx = max(0, (cols - len(title) + 1) // 2)
        safe_addstr(self.stdscr, 0, tx, title, curses.A_BOLD)
        safe_addstr(self.stdscr, 1, 0, "─" * cols)

        # Panels
        left_w = min(32, cols // 2)
        right_w = cols - left_w
        panel_h = rows - 3  # 2 for header + 1 for bottom border

        # Left panel
        left_title = "Scratchpads"
        safe_addstr(self.stdscr, 2, 0,
                   "╭" + left_title + "─" * max(0, left_w - 2 - len(left_title)) + "╮")

        items = ["Make new scratchpad"] + self.scratchpads
        inner_left_w = left_w - 2

        for i, item in enumerate(items):
            if i >= panel_h:
                break
            is_cur = (i == self.scratchpad_cursor)
            prefix = "> " if is_cur else "  "
            text = (prefix + item)[:inner_left_w].ljust(inner_left_w)
            attr = curses.A_REVERSE if is_cur else curses.A_NORMAL
            safe_addstr(self.stdscr, 3 + i, 0, "│")
            safe_addstr(self.stdscr, 3 + i, 1, text[:cols - 1], attr)
            if left_w - 1 < cols:
                safe_addstr(self.stdscr, 3 + i, left_w - 1, "│")

        for i in range(len(items), panel_h):
            safe_addstr(self.stdscr, 3 + i, 0, "│" + " " * inner_left_w)
            if left_w - 1 < cols:
                safe_addstr(self.stdscr, 3 + i, left_w - 1, "│")

        safe_addstr(self.stdscr, 3 + panel_h, 0,
                   "╰" + "─" * (left_w - 2) + "╯")

        # Right panel
        inner_right_w = right_w - 2
        safe_addstr(self.stdscr, 2, left_w,
                   "╭" + "─" * max(0, right_w - 2) + "╮")

        if self.scratchpad_cursor == 0:
            # No selection
            msg1 = "Select a scratchpad"
            msg2 = "No scratchpad selected"
            mx1 = left_w + 1 + max(0, (inner_right_w - len(msg1)) // 2)
            safe_addstr(self.stdscr, 3, mx1, msg1[:inner_right_w])
            safe_addstr(self.stdscr, 4, left_w + 1, msg2[:inner_right_w])
        else:
            scratch_name = self.scratchpads[self.scratchpad_cursor - 1]
            scratch_path = os.path.join(self.log_dir, SCRATCHPAD_DIR, scratch_name)
            try:
                with open(scratch_path, 'r', encoding='utf-8', errors='replace') as f:
                    content = f.read()
                for i, line in enumerate(content.split('\n')):
                    if 3 + i >= rows:
                        break
                    safe_addstr(self.stdscr, 3 + i, left_w + 1, line[:inner_right_w])
            except OSError:
                pass

        for i in range(panel_h):
            if left_w < cols:
                safe_addstr(self.stdscr, 3 + i, left_w, "│")
            if left_w + right_w - 1 < cols:
                safe_addstr(self.stdscr, 3 + i, left_w + right_w - 1, "│")

        safe_addstr(self.stdscr, 3 + panel_h, left_w,
                   "╰" + "─" * max(0, right_w - 2) + "╯")

        self.stdscr.refresh()

    def handle_key(self, key) -> bool:
        """Handle keyboard input. Returns False to quit."""
        if self.scratchpad_mode:
            return self.handle_scratchpad_key(key)

        if key == ord('q'):
            return False
        elif key == ord('s'):
            self.scratchpad_mode = True
            self.refresh_data()
        elif key in (ord('+'), ord('=')):
            self.current_year += 1
            try:
                self.cursor_date = self.cursor_date.replace(year=self.current_year)
            except ValueError:
                # Handle Feb 29 in non-leap years
                self.cursor_date = datetime.date(self.current_year, 
                                                 self.cursor_date.month, 28)
            self.section_cursor = 0
            self.tag_cursor = 0
            self.selected_section = None
            self.selected_tag = None
            self.refresh_data()
        elif key == ord('-'):
            self.current_year -= 1
            try:
                self.cursor_date = self.cursor_date.replace(year=self.current_year)
            except ValueError:
                self.cursor_date = datetime.date(self.current_year,
                                                 self.cursor_date.month, 28)
            self.section_cursor = 0
            self.tag_cursor = 0
            self.selected_section = None
            self.selected_tag = None
            self.refresh_data()
        elif key == 9:  # Tab
            self.focus = (self.focus + 1) % 3
        elif key == curses.KEY_BTAB:
            self.focus = (self.focus - 1) % 3
        elif key in (ord('j'), curses.KEY_DOWN):
            self._move_down()
        elif key in (ord('k'), curses.KEY_UP):
            self._move_up()
        elif key in (ord('l'), curses.KEY_RIGHT):
            if self.focus < 2:
                self.focus += 1
        elif key in (ord('h'), curses.KEY_LEFT):
            if self.focus > 0:
                self.focus -= 1
        elif key in (10, 13, curses.KEY_ENTER):
            self._open_current()
        elif key == ord('d'):
            if self.focus == 2:
                self._delete_log()

        return True

    def handle_scratchpad_key(self, key) -> bool:
        if key in (ord('s'), ord('q')):
            self.scratchpad_mode = False
        elif key in (ord('j'), curses.KEY_DOWN):
            max_idx = len(self.scratchpads)
            self.scratchpad_cursor = min(self.scratchpad_cursor + 1, max_idx)
        elif key in (ord('k'), curses.KEY_UP):
            self.scratchpad_cursor = max(0, self.scratchpad_cursor - 1)
        elif key in (10, 13, curses.KEY_ENTER):
            if self.scratchpad_cursor == 0:
                self._create_scratchpad()
            else:
                scratch_name = self.scratchpads[self.scratchpad_cursor - 1]
                scratch_path = os.path.join(self.log_dir, SCRATCHPAD_DIR, scratch_name)
                curses.endwin()
                open_editor(scratch_path)
                curses.doupdate()
                self.refresh_data()
        return True

    def _create_scratchpad(self):
        now = datetime.datetime.now()
        name = now.strftime("scratch_%Y%m%d_%H%M%S.md")
        scratch_path = os.path.join(self.log_dir, SCRATCHPAD_DIR, name)
        curses.endwin()
        open_editor(scratch_path)
        curses.doupdate()
        self.refresh_data()
        if name in self.scratchpads:
            self.scratchpad_cursor = self.scratchpads.index(name) + 1

    def _move_down(self):
        if self.focus == 0:
            max_idx = len(self.sections_list)
            if self.section_cursor < max_idx:
                self.section_cursor += 1
                if self.section_cursor == 0:
                    self.selected_section = None
                else:
                    self.selected_section = self.sections_list[self.section_cursor - 1][0]
                self.tag_cursor = 0
                self.selected_tag = None
                self._rebuild_tags_list()
        elif self.focus == 1:
            max_idx = len(self.tags_list)
            if self.tag_cursor < max_idx:
                self.tag_cursor += 1
                if self.tag_cursor == 0:
                    self.selected_tag = None
                else:
                    self.selected_tag = self.tags_list[self.tag_cursor - 1][0]
        elif self.focus == 2:
            new_date = self.cursor_date + datetime.timedelta(days=7)
            if new_date.year == self.current_year:
                self.cursor_date = new_date
            elif new_date.year > self.current_year:
                # Clamp to last day of year
                self.cursor_date = datetime.date(self.current_year, 12, 31)

    def _move_up(self):
        if self.focus == 0:
            if self.section_cursor > 0:
                self.section_cursor -= 1
                if self.section_cursor == 0:
                    self.selected_section = None
                else:
                    self.selected_section = self.sections_list[self.section_cursor - 1][0]
                self.tag_cursor = 0
                self.selected_tag = None
                self._rebuild_tags_list()
        elif self.focus == 1:
            if self.tag_cursor > 0:
                self.tag_cursor -= 1
                if self.tag_cursor == 0:
                    self.selected_tag = None
                else:
                    self.selected_tag = self.tags_list[self.tag_cursor - 1][0]
        elif self.focus == 2:
            new_date = self.cursor_date - datetime.timedelta(days=7)
            if new_date.year == self.current_year:
                self.cursor_date = new_date
            elif new_date.year < self.current_year:
                self.cursor_date = datetime.date(self.current_year, 1, 1)

    def _open_current(self):
        if self.focus == 2:
            log_path = get_log_filename(self.log_dir, self.cursor_date, self.log_fmt)
            curses.endwin()
            open_editor(log_path)
            curses.doupdate()
            self.refresh_data()

    def _delete_log(self):
        log_path = get_log_filename(self.log_dir, self.cursor_date, self.log_fmt)
        if os.path.exists(log_path):
            try:
                os.remove(log_path)
                self.refresh_data()
            except OSError:
                pass

    def show_password_dialog(self) -> str:
        """Show password input dialog"""
        rows, cols = self.stdscr.getmaxyx()

        # Draw dimmed background
        self.stdscr.erase()
        self.stdscr.bkgd(' ', curses.A_DIM)
        self.stdscr.refresh()

        # Dialog
        dlg_w = 35
        dlg_h = 8
        dlg_y = max(0, (rows - dlg_h) // 2)
        dlg_x = max(0, (cols - dlg_w) // 2)

        title = "Enter password for log files:"
        inner_w = dlg_w - 2
        title_padded = title + "─" * max(0, inner_w - len(title))

        try:
            self.stdscr.addstr(dlg_y, dlg_x, "╭" + title_padded + "╮")
            self.stdscr.addstr(dlg_y + 1, dlg_x, "├" + "─" * inner_w + "┤")
            self.stdscr.addstr(dlg_y + 2, dlg_x, "│" + " " * inner_w + "│")
            self.stdscr.addstr(dlg_y + 3, dlg_x, "│" + " " * inner_w + "│")
            self.stdscr.addstr(dlg_y + 4, dlg_x, "│" + " " * inner_w + "│")
            btn = "Submit"
            btn_x = dlg_x + (inner_w - len(btn) - 4) // 2 + 1
            self.stdscr.addstr(dlg_y + 4, btn_x, "┌" + "─" * (len(btn) + 2) + "┐")
            self.stdscr.addstr(dlg_y + 5, dlg_x, "│" + " " * inner_w + "│")
            self.stdscr.addstr(dlg_y + 5, btn_x, "│ " + btn + " │")
            self.stdscr.addstr(dlg_y + 6, dlg_x, "│" + " " * inner_w + "│")
            self.stdscr.addstr(dlg_y + 6, btn_x, "└" + "─" * (len(btn) + 2) + "┘")
            self.stdscr.addstr(dlg_y + 7, dlg_x, "╰" + "─" * inner_w + "╯")
        except curses.error:
            pass

        # Input field
        input_y = dlg_y + 3
        input_x = dlg_x + 2
        input_w = inner_w - 2

        curses.curs_set(1)
        self.stdscr.move(input_y, input_x)
        self.stdscr.refresh()

        chars = []
        while True:
            try:
                key = self.stdscr.get_wch()
            except curses.error:
                break

            if isinstance(key, str):
                code = ord(key)
            else:
                code = key

            if code in (10, 13):  # Enter
                break
            elif code in (curses.KEY_BACKSPACE, 127, 8):
                if chars:
                    chars.pop()
                    try:
                        self.stdscr.addstr(input_y, input_x, " " * input_w)
                        self.stdscr.addstr(input_y, input_x, "*" * len(chars))
                        self.stdscr.move(input_y, input_x + len(chars))
                        self.stdscr.refresh()
                    except curses.error:
                        pass
            elif 32 <= code < 256 and len(chars) < input_w:
                chars.append(chr(code))
                try:
                    self.stdscr.addstr(input_y, input_x + len(chars) - 1, "*")
                    self.stdscr.refresh()
                except curses.error:
                    pass

        curses.curs_set(0)
        self.stdscr.bkgd(' ', curses.A_NORMAL)
        return "".join(chars)

    def run(self):
        """Main event loop"""
        self.stdscr.nodelay(False)
        while True:
            self.draw()
            try:
                key = self.stdscr.get_wch()
                if isinstance(key, str):
                    key = ord(key)
            except KeyboardInterrupt:
                break
            except curses.error:
                continue
            if not self.handle_key(key):
                break


# ─────────────────────────────────────────────
# Entry Point
# ─────────────────────────────────────────────

def run_tui(log_dir, log_fmt, sunday_start, first_line_section, password=None):
    """Run the TUI application"""
    def main(stdscr):
        tui = CapsLogTUI(stdscr, log_dir, log_fmt, sunday_start, first_line_section)

        if has_cle(log_dir):
            if password is None:
                # Show interactive password dialog
                entered = tui.show_password_dialog()
                if not validate_password(log_dir, entered):
                    curses.endwin()
                    error_exit("Invalid password provided!")
            else:
                if not validate_password(log_dir, password):
                    curses.endwin()
                    error_exit("Invalid password provided!")
        elif password is not None:
            # Password provided but no .cle - just proceed normally
            pass

        tui.run()

    try:
        curses.wrapper(main)
    except SystemExit:
        raise
    except Exception as e:
        error_exit(str(e))


def main():
    """Main entry point"""
    args = sys.argv[1:]

    config_path = DEFAULT_CONFIG_PATH
    log_dir = None
    log_fmt = None
    sunday_start = False
    first_line_section = False
    password = None
    do_encrypt_flag = False
    do_decrypt_flag = False

    i = 0
    while i < len(args):
        arg = args[i]

        if arg in ('-h', '--help'):
            show_help()
            sys.exit(0)
        elif arg in ('-c', '--config'):
            if i + 1 < len(args):
                i += 1
                config_path = args[i]
            else:
                error_exit("option '--config' requires an argument")
        elif arg == '--log-dir-path':
            if i + 1 < len(args):
                i += 1
                log_dir = args[i]
            else:
                error_exit("option '--log-dir-path' requires an argument")
        elif arg == '--log-name-format':
            if i + 1 < len(args):
                i += 1
                log_fmt = args[i]
            else:
                error_exit("option '--log-name-format' requires an argument")
        elif arg == '--sunday-start':
            sunday_start = True
        elif arg == '--first-line-section':
            first_line_section = True
        elif arg == '--password':
            if i + 1 < len(args):
                i += 1
                password = args[i]
            else:
                error_exit("option '--password' requires an argument")
        elif arg == '--encrypt':
            do_encrypt_flag = True
        elif arg == '--decrypt':
            do_decrypt_flag = True
        elif arg.startswith('-'):
            error_exit(f"unrecognised option '{arg}'")

        i += 1

    # Load config (required for all non-help commands)
    try:
        config = parse_config(config_path)
    except FileNotFoundError as e:
        error_exit(str(e))
        return

    # Apply config overrides
    if log_dir is None:
        log_dir = config.get('log-dir-path', DEFAULT_LOG_DIR)
    if log_fmt is None:
        log_fmt = config.get('log-name-format', DEFAULT_LOG_FORMAT)
    if not sunday_start:
        sunday_start = bool(config.get('sunday-start', False))
    if not first_line_section:
        first_line_section = bool(config.get('first-line-section', False))
    if password is None and 'password' in config:
        password = config['password']

    log_dir = os.path.expanduser(log_dir)

    # Handle encrypt
    if do_encrypt_flag:
        if not password:
            error_exit("Password must be provided when encrypting logs!")

        # Validate directory
        try:
            list(os.scandir(log_dir))
        except (OSError, FileNotFoundError) as e:
            print("Applying crypto...")
            error_exit(f"filesystem error: directory iterator cannot open directory: "
                      f"{e.strerror} [{log_dir}]")

        do_encrypt(log_dir, password)
        return

    # Handle decrypt
    if do_decrypt_flag:
        if not password:
            error_exit("Password must be provided when decrypting logs!")

        try:
            list(os.scandir(log_dir))
        except (OSError, FileNotFoundError) as e:
            print("Applying crypto...")
            error_exit(f"filesystem error: directory iterator cannot open directory: "
                      f"{e.strerror} [{log_dir}]")

        do_decrypt(log_dir, password)
        return

    # Validate password if .cle exists (before opening TUI)
    # But only if password was given on command line
    if password is not None and has_cle(log_dir):
        if not validate_password(log_dir, password):
            error_exit("Invalid password provided!")

    # Create dirs
    os.makedirs(log_dir, exist_ok=True)
    os.makedirs(os.path.join(log_dir, SCRATCHPAD_DIR), exist_ok=True)

    # Run TUI
    run_tui(log_dir, log_fmt, sunday_start, first_line_section, password)


if __name__ == '__main__':
    main()
